classDiagram
  direction LR
  class Repository~T~ {
    <<abstract>>
    #String table
    +findById(id UUID)* T
    +count()$ int
  }
  class EventBus~E~ {
    +publish(event E) void
    +subscribe(handler Handler) void
  }
  class OrderService {
    +placeOrder(cmd Command) Order
    +cancel(id UUID) void
  }
  Repository <|-- OrderService : extends
  OrderService --> EventBus : publishes
  EventBus --> OrderService : dispatches
